import{_ as t,o,c as a,a3 as d}from"./chunks/framework.qCVWde4n.js";const m=JSON.parse(`{"title":"The phone's own capabilities","description":"","frontmatter":{},"headers":[],"relativePath":"device.md","filePath":"device.md"}`),n={name:"device.md"};function s(i,e,r,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="the-phone-s-own-capabilities" tabindex="-1">The phone&#39;s own capabilities <a class="header-anchor" href="#the-phone-s-own-capabilities" aria-label="Permalink to &quot;The phone&#39;s own capabilities&quot;">​</a></h1><blockquote><p><strong>Design record of the Python line.</strong> In the current Android app the phone&#39;s capabilities are OpenMinis&#39;s device tools, and the computers are reached through Reach and the hub (<a href="./android">android.md</a>, <a href="./hub">hub.md</a>); the &quot;connect build&quot; mentioned below no longer exists.</p></blockquote><p>On a phone, nanoMuse can reach what is on it: the clipboard, the calendar, the contacts, where the phone is, the clock&#39;s alarms and timers, the notification shade, and the photo library through the system picker. This page is about how that works, what each tool may do, what it asks the user, and what it deliberately cannot do.</p><p>The rule of the design: <strong>the model gets tools, the user gets Android&#39;s own dialogs.</strong> nanoMuse never grants itself anything. Every permission is asked for by the platform&#39;s dialog, the photo library is only ever seen through the platform&#39;s picker, and alarms are handed to the clock app the user already has. The Python brain does not change to run on a phone; the Kotlin side is a small tool host.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> nanomuse serve (Python, in PRoot)                 the app (Kotlin)</span></span>
<span class="line"><span> ┌──────────────────────────────┐   HTTP, 127.0.0.1    ┌───────────────────────────────┐</span></span>
<span class="line"><span> │ MCP client  ── device__* ────┼──────────────────────►│ McpEndpoint  (Streamable HTTP) │</span></span>
<span class="line"><span> │ Sentinel: per-tool defaults  │   Bearer / ?token=    │  DeviceTools: 13 tools         │</span></span>
<span class="line"><span> │ nanomuse-device (CLI bridge) │◄──────────────────────┤  Ask: Android&#39;s dialogs        │</span></span>
<span class="line"><span> └──────────────────────────────┘   SSE + heartbeats    │  DeviceAskActivity (invisible) │</span></span>
<span class="line"><span>                                                        └───────────────────────────────┘</span></span></code></pre></div><h2 id="how-the-tools-reach-the-model" tabindex="-1">How the tools reach the model <a class="header-anchor" href="#how-the-tools-reach-the-model" aria-label="Permalink to &quot;How the tools reach the model&quot;">​</a></h2><p>The app starts an MCP server on <code>127.0.0.1</code> (a random port, a random token, both handed to the runtime as <code>NANOMUSE_HOST_URL</code> and <code>NANOMUSE_HOST_TOKEN</code>). <code>nanomuse serve</code> sees them and adds the server as <code>device</code> — no configuration, nothing to install — so the tools appear like any other MCP server&#39;s, named <code>device__&lt;tool&gt;</code> (<code>device__calendar_list</code>, <code>device__clipboard_read</code> …). The system prompt gets a short <em>This phone</em> section listing them, with the ground rules the model has to know: the first use of a capability makes Android ask the user, and the clipboard can only be read while the app is on screen.</p><p>The endpoint speaks <a href="https://modelcontextprotocol.io/specification/2025-03-26/basic/transports" target="_blank" rel="noreferrer">Streamable HTTP</a>: <code>POST /mcp</code> with JSON-RPC; <code>tools/call</code> answers as an SSE stream with a <code>: keep-alive</code> line every 8 s, because a call may wait minutes for the user to answer a dialog; <code>GET /mcp</code> is <code>405</code>; the token is a <code>Bearer</code> header or <code>?token=</code>; the <code>Mcp-Session-Id</code> header is issued on <code>initialize</code> and the client&#39;s <code>protocolVersion</code> is echoed back. Only <code>/mcp</code> exists. It is bound to the loopback interface and refuses anything without the token (compared in constant time).</p><p>Scripts the agent runs inside the sandbox reach the same tools through the CLI bridge (<a href="./local-runtime#the-python-side-on-a-phone">local-runtime.md</a>): <code>nanomuse-device clipboard read</code>, <code>nanomuse-device calendar list from=2026-09-24</code>, <code>nanomuse-device alarm set hour=7 minute=30 message=Train</code>, <code>nanomuse-device notify title=Done body=Booked</code>, <code>nanomuse-device location</code>, <code>nanomuse-device photo pick</code>; <code>nanomuse-device list</code> shows what the phone has. Each goes through the same Sentinel as a model call.</p><h2 id="the-tools" tabindex="-1">The tools <a class="header-anchor" href="#the-tools" aria-label="Permalink to &quot;The tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>tool</th><th>does</th><th>arguments</th><th>Android permission</th><th>risk</th><th>asks in <code>ask</code> mode?</th></tr></thead><tbody><tr><td><code>clipboard_read</code></td><td>the clipboard&#39;s text</td><td>—</td><td>none, but <strong>only while the app is on screen</strong> (Android 10+)</td><td>moderate, private</td><td>no</td></tr><tr><td><code>clipboard_write</code></td><td>put text on the clipboard</td><td><code>text</code></td><td>none</td><td>safe</td><td>no</td></tr><tr><td><code>notify</code></td><td>post a notification; tapping it opens the chat</td><td><code>title</code>, <code>body</code>, <code>thread</code></td><td><code>POST_NOTIFICATIONS</code> (13+)</td><td>safe</td><td>no</td></tr><tr><td><code>calendars</code></td><td>the calendars on the phone</td><td>—</td><td><code>READ_CALENDAR</code></td><td>moderate, private</td><td>no</td></tr><tr><td><code>calendar_list</code></td><td>events in a range, optional word filter</td><td><code>from</code>, <code>to</code>, <code>query</code>, <code>calendar_id</code>, <code>limit</code></td><td><code>READ_CALENDAR</code></td><td>moderate, private</td><td>no</td></tr><tr><td><code>calendar_create</code></td><td>add an event; all-day takes dates</td><td><code>title</code>, <code>start</code>, <code>end</code>, <code>all_day</code>, <code>location</code>, <code>description</code>, <code>calendar_id</code>, <code>reminder_minutes</code></td><td><code>WRITE_CALENDAR</code></td><td>moderate</td><td>no</td></tr><tr><td><code>calendar_update</code></td><td>change the fields given</td><td><code>id</code>, <code>title</code>, <code>start</code>, <code>end</code>, <code>all_day</code>, <code>location</code>, <code>description</code></td><td><code>WRITE_CALENDAR</code></td><td>moderate</td><td>no</td></tr><tr><td><code>calendar_delete</code></td><td>delete an event</td><td><code>id</code></td><td><code>WRITE_CALENDAR</code></td><td><strong>sensitive</strong></td><td><strong>yes</strong></td></tr><tr><td><code>contacts_search</code></td><td>people by name, number or e-mail; read-only</td><td><code>query</code>, <code>limit</code></td><td><code>READ_CONTACTS</code></td><td>moderate, private</td><td>no</td></tr><tr><td><code>location</code></td><td>coordinates, accuracy, address when it can be looked up</td><td><code>accuracy</code> (<code>fine</code>/<code>coarse</code>), <code>max_age_seconds</code></td><td><code>ACCESS_FINE_LOCATION</code> / <code>ACCESS_COARSE_LOCATION</code></td><td>moderate, private</td><td>no</td></tr><tr><td><code>alarm_set</code></td><td>an alarm in the clock app</td><td><code>hour</code>, <code>minute</code>, <code>message</code>, <code>days</code>, <code>vibrate</code></td><td><code>SET_ALARM</code> (granted at install)</td><td>moderate</td><td>no</td></tr><tr><td><code>timer_set</code></td><td>a countdown in the clock app</td><td><code>seconds</code> or <code>minutes</code>, <code>message</code></td><td><code>SET_ALARM</code></td><td>moderate</td><td>no</td></tr><tr><td><code>photo_pick</code></td><td>the user chooses photos in the system picker; copies land in the workspace</td><td><code>max</code> (≤ 10), <code>why</code></td><td>none — the Photo Picker needs no permission</td><td>safe, private</td><td>no</td></tr></tbody></table><p><em>Risk</em> and <em>private</em> are the Sentinel defaults from <code>DEVICE_TOOLS</code> in <code>nanomuse/runtime.py</code>, applied per tool through the <code>tools</code> map of the MCP server entry (<a href="./configuration#mcp-servers">configuration.md</a>). &quot;Asks&quot; is the <code>ask</code> mode column of <a href="./sentinel">sentinel.md</a>; in <code>strict</code> mode every moderate tool asks too. <em>Private</em> tools taint the session: after <code>contacts_search</code> or <code>location</code>, anything that sends data to an unknown host asks. Times are phone-local (<code>YYYY-MM-DD HH:MM</code>, or a date for all-day); the end of an all-day event is shown as its last day. The address in <code>location</code> comes from the platform geocoder when the phone has one; without it the tool returns coordinates only.</p><p>The Kotlin list (<code>DeviceTools.kt</code>) and the Python table (<code>DEVICE_TOOLS</code>) must agree; <code>tests/test_bridge.py</code> checks the names and the defaults.</p><h2 id="what-the-user-sees" tabindex="-1">What the user sees <a class="header-anchor" href="#what-the-user-sees" aria-label="Permalink to &quot;What the user sees&quot;">​</a></h2><p>Everything the tools need from the user is an Android dialog, opened by an invisible activity of the app (<code>DeviceAskActivity</code>) so it can appear from wherever the agent is running. Android 10+ does not let a background app start an activity, so there are two routes:</p><ul><li><strong>The app is on screen</strong> → the dialog appears right away over it.</li><li><strong>The app is in the background</strong> → a notification (<em>nanoMuse needs a permission</em> / <em>nanoMuse wants to read the clipboard</em> / <em>… wants a photo</em>) with one line on why; tapping it brings up the dialog. The tool call waits in the meantime (2 min for a permission, 1.5 min for the clipboard, 4 min for photos), the model is told what happened either way.</li></ul><p>Three outcomes reach the model, in words it can pass on: granted (the tool runs); <em>the user did not allow it — do not ask again now, it can be allowed later in Android&#39;s settings</em>; <em>nobody answered — ask the user to open nanoMuse and try again</em>.</p><p>Specific rules, each from the platform rather than from us:</p><ul><li><strong>Clipboard.</strong> Since Android 10 only the app with the focus may read the clipboard. <code>clipboard_read</code> from the background therefore goes through the notification route; the read happens the moment the user taps it. Writing works any time.</li><li><strong>Alarms and timers.</strong> They are handed to the clock app with the standard <code>AlarmClock</code> intents, skipping its UI (the alarm appears in the clock as if set by hand). From the foreground — or when the app has the <em>display over other apps</em> permission — the hand-off is immediate; from the background Android forbids starting another app, so a notification is posted and the alarm is set when the user taps it. The clock app is the one the user has; on a phone without one the tool says so.</li><li><strong>Photos.</strong> Only the <a href="https://developer.android.com/training/data-storage/shared/photopicker" target="_blank" rel="noreferrer">Photo Picker</a>: the user picks, the app receives exactly those items, copies them into <code>workspace/attachments/&lt;date&gt;/</code> and returns the paths. Nothing else in the library is readable, no <code>READ_MEDIA_IMAGES</code> is requested, and the picker itself says so on screen.</li><li><strong>Location.</strong> Uses the platform <code>LocationManager</code>, no Play services; the last known fix when it is fresh enough (<code>max_age_seconds</code>, default 2 min), otherwise a new one with up to 25 s to arrive. <code>coarse</code> asks for the approximate permission only.</li><li><strong>Contacts</strong> are read-only. <strong>Calendars</strong> are read and written through the platform provider; deleting is the one action that always asks.</li><li><strong>Notifications</strong> posted by <code>notify</code> go to the normal channel; tapping opens the thread. Reading the notification shade is <strong>not offered</strong>: it needs the notification-listener special access, which Android treats as a device-wide privilege; if it comes (P2), it will be its own switch, off by default, with its own row in the Sentinel table.</li></ul><h2 id="the-workspace-in-the-files-app" tabindex="-1">The workspace in the Files app <a class="header-anchor" href="#the-workspace-in-the-files-app" aria-label="Permalink to &quot;The workspace in the Files app&quot;">​</a></h2><p>The local build registers a <code>DocumentsProvider</code>: the agent&#39;s workspace appears as a root named after the agent in the system Files app and in every open/save dialog on the phone (Storage Access Framework). Files the agent made are ordinary files; a file dropped there is in the workspace. Hidden entries and the browser profile are not shown. The connect build has no workspace on the phone and shows no root.</p><h2 id="sharing-into-nanomuse" tabindex="-1">Sharing into nanoMuse <a class="header-anchor" href="#sharing-into-nanomuse" aria-label="Permalink to &quot;Sharing into nanoMuse&quot;">​</a></h2><p>nanoMuse is in the system share sheet for text, links and files. A share becomes a <strong>new conversation</strong>: files are uploaded to the workspace (<code>attachments/&lt;date&gt;/…</code>), the thread is named after the subject or the first file, and the chat opens with the shared text as a draft and the files as attachment chips, waiting for what to do with them — nothing is sent to the model until the user says so. Both builds do this (the connect build uploads to the computer).</p><h2 id="connect-mode" tabindex="-1">Connect mode <a class="header-anchor" href="#connect-mode" aria-label="Permalink to &quot;Connect mode&quot;">​</a></h2><p>The connect build (the phone as a remote for <code>nanomuse serve</code> on a computer) has the same Kotlin tools but the server cannot reach <code>127.0.0.1</code> on the phone; it would need a relay over the phone&#39;s WebSocket. That is planned (P1, <a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/launch-checklist.md" target="_blank" rel="noreferrer">launch-checklist.md</a>); until then the device tools are a feature of running on the phone.</p><h2 id="testing-without-a-phone" tabindex="-1">Testing without a phone <a class="header-anchor" href="#testing-without-a-phone" aria-label="Permalink to &quot;Testing without a phone&quot;">​</a></h2><p>The emulator (x86_64) cannot run the arm64 PRoot runtime, but the tool host can be exercised directly: the connect <strong>debug</strong> build starts the MCP server on its own and logs <code>device MCP (debug): http://127.0.0.1:&lt;port&gt;/mcp token=&lt;token&gt;</code>. Then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:9410</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">por</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># any MCP client, e.g. the reference Python one:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   streamable_http_client(&quot;http://127.0.0.1:9410/mcp?token=&lt;token&gt;&quot;)</span></span></code></pre></div><p><code>adb shell pm revoke &lt;app id&gt; android.permission.READ_CALENDAR</code> brings the permission dialogs back; <code>adb shell input keyevent KEYCODE_HOME</code> exercises the notification route; <code>adb emu geo fix &lt;lon&gt; &lt;lat&gt;</code> feeds <code>location</code>. <code>McpEndpointTest</code> covers the transport itself on the JVM (initialize, <code>tools/list</code>, an SSE call with heartbeats, a failing tool as <code>isError</code>, bad token and method).</p><h2 id="not-in-this-release" tabindex="-1">Not in this release <a class="header-anchor" href="#not-in-this-release" aria-label="Permalink to &quot;Not in this release&quot;">​</a></h2><p>Reading notifications, writing contacts, the whole photo library, SMS and call logs, and the connect-mode relay. Each is a switch of its own when it comes, off by default.</p>`,31)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
